(function(){const media=matchMedia('(prefers-color-scheme: dark)');let preference='system';try{preference=localStorage.getItem('forma-theme')||'system'}catch{}function apply(){document.documentElement.dataset.theme=preference==='system'?(media.matches?'dark':'light'):preference}window.formaTheme={get:()=>preference,set(value){preference=value;try{localStorage.setItem('forma-theme',value)}catch{}apply()}};apply();media.addEventListener('change',()=>{if(preference==='system')apply()})})();
